#!/usr/bin/env bash
# Cursor subagentStart hook (harness/cursor/tea-rags/scripts/subagent-start.sh,
# generated by scripts/gen-harness-cursor.ts; bd tea-rags-mcp-xkbkv): the Cursor
# form of the Claude plugin's enforce-tearags-search.sh. It answers
# {"permission":"allow","additional_context":<search block>}, prefixed with the
# repository's alias when `tea-rags project exist --repository --print-name`
# resolves one. subagentStart is a permission hook: whatever happens, stdout is
# a schema-valid allow and the exit code is 0 — the hook never blocks a subagent.
set -u
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
HOOK="$ROOT/harness/cursor/tea-rags/scripts/subagent-start.sh"
PASS=0; FAIL=0
note() { if [ "$1" = 0 ]; then PASS=$((PASS+1)); echo "ok   - $2"; else FAIL=$((FAIL+1)); echo "FAIL - $2"; fi; }

FAKEBIN="$(mktemp -d)"; CALLS="$(mktemp)"; SCRATCH="$(mktemp -d)"
cat > "$FAKEBIN/tea-rags" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$CALLS"
printf '%s\n' "$FAKE_OUT"
exit "$FAKE_EXIT"
EOF
chmod +x "$FAKEBIN/tea-rags"
NOCLI="$(mktemp -d)"; ln -s "$(command -v jq)" "$NOCLI/jq"
BASE_PATH="/usr/bin:/bin"
export CALLS

run() { # $1=json payload, $2=fake stdout, $3=fake exit, [$4=PATH], [$5=CURSOR_PROJECT_DIR]
  : > "$CALLS"; export FAKE_OUT="$2" FAKE_EXIT="$3"
  OUT=$(printf '%s' "$1" | env -u TEA_RAGS_BIN HOME="$SCRATCH" CURSOR_PROJECT_DIR="${5-/repo}" PATH="${4:-$FAKEBIN:$NOCLI:$BASE_PATH}" bash "$HOOK" 2>/dev/null)
  CODE=$?
}
START='{"hook_event_name":"subagentStart","subagent_id":"s1","subagent_type":"explore","task":"find X","workspace_roots":["/ws"]}'
ctx() { printf '%s' "$OUT" | jq -r '.additional_context // empty' 2>/dev/null; }
allowed() { [ "$CODE" = 0 ] && [ "$(printf '%s' "$OUT" | jq -r '.permission' 2>/dev/null)" = allow ]; }

[ -f "$HOOK" ]
note $? "hook script is generated"

run "$START" "tea-rags" 0
{ allowed && ctx | grep -qF 'tea-rags project alias for this repository: `tea-rags`'; }; note $? "alias line leads the injected block"
ctx | grep -qF 'pass project="tea-rags" together with path=<your working directory>'; note $? "alias line says to pass project with path"
[ "$(ctx | wc -c)" -gt 300 ]; note $? "the search block follows the alias line"
grep -qxF 'project exist --path /repo --repository --print-name' "$CALLS"; note $? "alias resolves CURSOR_PROJECT_DIR by repository"

run "$START" "tea-rags" 0 "" ""
grep -qxF 'project exist --path /ws --repository --print-name' "$CALLS"; note $? "no CURSOR_PROJECT_DIR → first workspace root"

run "$START" "" 1
{ allowed && [ -n "$(ctx)" ] && ! ctx | grep -qF 'project alias'; }; note $? "unregistered repository → block without alias"

run "$START" "tea-rags" 0 "$NOCLI:$BASE_PATH"
{ allowed && [ -n "$(ctx)" ] && ! ctx | grep -qF 'project alias'; }; note $? "missing tea-rags CLI → block without alias"

run 'not json' "tea-rags" 0
{ allowed && [ -n "$(ctx)" ]; }; note $? "malformed hook input still allows with the block"

[ "$(ctx | wc -c)" -le 10000 ]; note $? "context stays within Cursor's 10000-char limit"

rm -rf "$FAKEBIN" "$NOCLI" "$CALLS" "$SCRATCH"
echo "# $PASS passed, $FAIL failed"
[ "$FAIL" = 0 ]
